        if index == len(pattern):
            return current_value

        char = pattern[index]
        if char == 'L':
            return dfs(index + 1, current_value * 2)
        elif char == 'R':
            return dfs(index + 1, current_value * 2 + 1)
        elif char == 'P':
            return dfs(index + 1, current_value)
        else:  # char == '*'
            return (dfs(index + 1, current_value * 2) +
                    dfs(index + 1, current_value * 2 + 1) +
                    dfs(index + 1, current_value))

    return dfs(0, 1)

